with d as (select value r from jsonb_array_elements($q$[{"slug":"turkish-eggs","title":"Turkish Eggs","cuisine":"turkish","meal_types":["breakfast","lunch"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":20,"recipe":{"id":"turkish-eggs","title":"Turkish Eggs","summary":"Poached eggs on garlicky yoghurt, under a spoonful of sizzling Aleppo pepper butter.","cuisine":"turkish","diets":["vegetarian"],"mealTypes":["breakfast","lunch"],"difficulty":"easy","prepMinutes":10,"cookMinutes":10,"servings":2,"onePot":false,"ingredientGroups":[{"title":"Yoghurt","items":[{"item":"Greek yoghurt","raw":"250g Greek yoghurt, at room temperature","quantity":250,"unit":"g","ingredientId":"greek-yoghurt","prep":"at room temperature"},{"item":"garlic","raw":"1 garlic clove, finely grated","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"finely grated"},{"item":"salt","raw":"1/4 tsp salt","quantity":0.25,"unit":"tsp","ingredientId":"salt"}]},{"title":"Eggs and butter","items":[{"item":"eggs","raw":"4 eggs, very fresh","quantity":4,"ingredientId":"egg","prep":"very fresh"},{"item":"white vinegar","raw":"1 tbsp white vinegar","quantity":1,"unit":"tbsp","ingredientId":"white-vinegar"},{"item":"butter","raw":"40g butter","quantity":40,"unit":"g","ingredientId":"butter"},{"item":"Aleppo pepper","raw":"1 tsp Aleppo pepper (or 1/2 tsp chilli flakes)","quantity":1,"unit":"tsp","ingredientId":"aleppo-pepper","note":"or 1/2 tsp chilli flakes"},{"item":"smoked paprika","raw":"1/2 tsp smoked paprika","quantity":0.5,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"dill","raw":"1 tbsp dill, chopped","quantity":1,"unit":"tbsp","ingredientId":"dill","prep":"chopped"}]},{"title":"To serve","items":[{"item":"sourdough","raw":"2 slices sourdough (or Turkish bread), thickly cut and toasted","quantity":2,"unit":"slice","ingredientId":"sourdough","prep":"thickly cut and toasted","note":"or Turkish bread"}]}],"steps":[{"text":"Stir the yoghurt, garlic and salt together and spread over two shallow bowls. It should be at room temperature, not fridge-cold, so take it out while you get everything else ready."},{"text":"Bring a wide saucepan of water to a gentle simmer and add the vinegar. Crack each egg into a cup. Stir the water to make a slow whirlpool, slip in two eggs and poach for 3 minutes, until the whites are set and the yolks still soft. Lift out with a slotted spoon onto paper towel. Repeat with the other two."},{"text":"Melt the butter in a small pan over medium heat until it foams and smells nutty. Take it off the heat and stir in the Aleppo pepper and smoked paprika."},{"text":"Sit two eggs on each bowl of yoghurt, spoon over the red butter until it pools, sizzling and glossy, and scatter with dill. Serve straight away with the toast for dipping."}],"notes":["Soft-yolked eggs aren't recommended for pregnant people, young children, older people or anyone with a weakened immune system. Poach for 5 minutes instead, until the yolks are firm.","The freshest eggs hold together best when poached. Older eggs spread into wispy whites.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"chilaquiles","title":"Chilaquiles","cuisine":"mexican","meal_types":["breakfast","lunch"],"diets":["vegetarian","no-gluten"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"chilaquiles","title":"Chilaquiles","summary":"Corn chips softened in a smoky tomato salsa, topped with fried eggs, feta and avocado.","cuisine":"mexican","diets":["vegetarian","no-gluten"],"mealTypes":["breakfast","lunch"],"difficulty":"easy","prepMinutes":10,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Salsa","items":[{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, roughly chopped","quantity":1,"ingredientId":"brown-onion","prep":"roughly chopped"},{"item":"garlic","raw":"2 garlic cloves, sliced","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"sliced"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"chipotle in adobo","raw":"1 chipotle in adobo, plus 1 tsp of the sauce","quantity":1,"ingredientId":"chipotle-in-adobo","prep":"plus 1 tsp of the sauce"},{"item":"ground cumin","raw":"1/2 tsp ground cumin","quantity":0.5,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"vegetable stock","raw":"250ml vegetable stock","quantity":250,"unit":"ml","ingredientId":"vegetable-stock"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"Chilaquiles","items":[{"item":"plain salted corn chips","raw":"200g plain salted corn chips","quantity":200,"unit":"g","ingredientId":"corn-chips"},{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"neutral oil","raw":"1 tbsp neutral oil, for frying","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil","prep":"for frying"},{"item":"feta","raw":"80g feta, crumbled","quantity":80,"unit":"g","ingredientId":"feta","prep":"crumbled"},{"item":"avocado","raw":"1 avocado, sliced","quantity":1,"ingredientId":"avocado","prep":"sliced"},{"item":"small red onion","raw":"1/2 small red onion, very thinly sliced","quantity":0.5,"ingredientId":"red-onion","prep":"very thinly sliced"},{"item":"sour cream","raw":"80g sour cream","quantity":80,"unit":"g","ingredientId":"sour-cream"},{"item":"coriander leaves","raw":"Handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander"},{"item":"Lime wedges","raw":"Lime wedges, to serve","ingredientId":"lime","prep":"to serve"}]}],"steps":[{"text":"Heat the oil in a large frying pan over medium heat. Cook the onion for 5 minutes until soft, then add the garlic for 1 minute."},{"text":"Add the tomatoes, chipotle and its sauce, cumin, stock and salt. Simmer for 8 minutes, then blend until smooth with a stick blender (or in a blender, carefully, as it's hot). Taste for salt."},{"text":"Bring the salsa back to a simmer in the pan. Tip in the corn chips and fold gently until every chip is coated. Take it off the heat; the chips should soften at the edges but keep some crunch."},{"text":"In a second pan, heat the oil over medium-high heat and fry the eggs for 3 to 4 minutes, until the whites are set."},{"text":"Divide the chilaquiles between plates. Top each with an egg, feta, avocado, red onion, a spoonful of sour cream and coriander. Serve with lime wedges, and eat straight away before the chips go soggy."}],"notes":["Runny-yolked eggs aren't recommended for pregnant people, young children, older people or anyone with a weakened immune system. Cover the pan for the last minute so the yolks set.","Thick, plain corn chips hold up best. Thin or flavoured ones turn to mush.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"buttermilk-pancakes","title":"Buttermilk Pancakes","cuisine":"american","meal_types":["breakfast"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"buttermilk-pancakes","title":"Buttermilk Pancakes","summary":"Tall, fluffy weekend pancakes with maple syrup, berries and a little melting butter.","cuisine":"american","diets":["vegetarian"],"mealTypes":["breakfast"],"difficulty":"easy","prepMinutes":10,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Batter","items":[{"item":"plain flour","raw":"300g plain flour","quantity":300,"unit":"g","ingredientId":"plain-flour"},{"item":"baking powder","raw":"2 tsp baking powder","quantity":2,"unit":"tsp","ingredientId":"baking-powder"},{"item":"bicarbonate soda","raw":"1/2 tsp bicarbonate soda","quantity":0.5,"unit":"tsp","ingredientId":"bicarbonate-soda"},{"item":"caster sugar","raw":"2 tbsp caster sugar","quantity":2,"unit":"tbsp","ingredientId":"caster-sugar"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"buttermilk","raw":"500ml buttermilk","quantity":500,"unit":"ml","ingredientId":"buttermilk"},{"item":"eggs","raw":"2 eggs","quantity":2,"ingredientId":"egg"},{"item":"butter","raw":"50g butter, melted, plus extra for the pan","quantity":50,"unit":"g","ingredientId":"butter","prep":"melted, plus extra for the pan"},{"item":"vanilla extract","raw":"1 tsp vanilla extract","quantity":1,"unit":"tsp","ingredientId":"vanilla-extract"}]},{"title":"To serve","items":[{"item":"Maple syrup","raw":"Maple syrup","ingredientId":"maple-syrup"},{"item":"frozen mixed berries","raw":"150g frozen mixed berries, thawed (or fresh berries)","quantity":150,"unit":"g","ingredientId":"frozen-berries","prep":"thawed","note":"or fresh berries"},{"item":"Butter","raw":"Butter","ingredientId":"butter"}]}],"steps":[{"text":"Whisk the flour, baking powder, bicarbonate soda, sugar and salt in a large bowl."},{"text":"In a jug, whisk the buttermilk, eggs, melted butter and vanilla. Pour into the dry ingredients and fold with a spatula until just combined. Lumps are fine; over-mixing makes tough pancakes. Rest for 5 minutes while the pan heats."},{"text":"Heat a large non-stick frying pan over medium-low heat and brush with a little butter. Pour in 1/3 cup of batter per pancake, leaving room to spread."},{"text":"Cook for 2 to 3 minutes, until bubbles pop on the surface and the edges look set. Flip and cook for 1 to 2 minutes more, until golden and springy. Keep warm in a low oven while you cook the rest."},{"text":"Serve stacked, with maple syrup, berries and a little butter."}],"notes":["No buttermilk? Stir 2 tbsp lemon juice into 500ml milk and leave for 5 minutes.","If the first pancake browns before it bubbles, turn the heat down. The first one is always the test."],"source":"user","provenance":"ai-draft"}},{"slug":"kedgeree","title":"Kedgeree","cuisine":"british","meal_types":["breakfast","lunch","dinner"],"diets":["pescatarian","no-gluten"],"difficulty":"easy","total_minutes":35,"recipe":{"id":"kedgeree","title":"Kedgeree","summary":"Gently curried rice with flakes of hot-smoked salmon, soft-boiled eggs and lots of parsley.","cuisine":"british","diets":["pescatarian","no-gluten"],"mealTypes":["breakfast","lunch","dinner"],"difficulty":"easy","prepMinutes":10,"cookMinutes":25,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"basmati rice","raw":"300g basmati rice, rinsed","quantity":300,"unit":"g","ingredientId":"basmati-rice","prep":"rinsed"},{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"butter","raw":"40g butter","quantity":40,"unit":"g","ingredientId":"butter"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"mild curry powder","raw":"2 tsp mild curry powder","quantity":2,"unit":"tsp","ingredientId":"curry-powder"},{"item":"ground turmeric","raw":"1/2 tsp ground turmeric","quantity":0.5,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"water","raw":"600ml water","quantity":600,"unit":"ml","ingredientId":"water"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"frozen peas","raw":"120g frozen peas","quantity":120,"unit":"g","ingredientId":"frozen-peas"},{"item":"hot-smoked salmon","raw":"300g hot-smoked salmon, skin removed, flaked","quantity":300,"unit":"g","ingredientId":"smoked-salmon","prep":"skin removed, flaked"},{"item":"flat-leaf parsley","raw":"1/2 bunch flat-leaf parsley, chopped","quantity":0.5,"unit":"bunch","ingredientId":"parsley","prep":"chopped"},{"item":"lemon","raw":"Juice of 1/2 lemon","quantity":0.5,"ingredientId":"lemon","prep":"juiced"},{"item":"Lemon wedges","raw":"Lemon wedges, to serve","ingredientId":"lemon","prep":"to serve"}]}],"steps":[{"text":"Lower the eggs into a pan of boiling water and cook for 7 minutes. Move to a bowl of cold water, then peel and quarter."},{"text":"Melt the butter in a wide saucepan with a lid over medium heat. Cook the onion for 6 minutes until soft and sweet. Stir in the curry powder and turmeric for 30 seconds."},{"text":"Add the rice and stir to coat in the butter. Pour in the water, add the salt and bring to the boil. Cover, turn the heat to low and cook for 12 minutes."},{"text":"Scatter the peas over the rice, cover again and leave off the heat for 5 minutes, so the rice finishes steaming and the peas warm through."},{"text":"Fluff the rice with a fork. Gently fold in the salmon, most of the parsley and the lemon juice. Top with the eggs and the rest of the parsley, and serve with lemon wedges."}],"notes":["The eggs are jammy at 7 minutes. For pregnant people, young children, older people or anyone with a weakened immune system, boil them for 10 minutes.","Leftover rice should go in the fridge within an hour and be eaten within a day.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"bircher-muesli","title":"Bircher Muesli","cuisine":"modern-australian","meal_types":["breakfast"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":495,"recipe":{"id":"bircher-muesli","title":"Bircher Muesli","summary":"Oats soaked overnight with apple and yoghurt, ready in the fridge when you wake up.","cuisine":"modern-australian","diets":["vegetarian"],"mealTypes":["breakfast"],"difficulty":"easy","prepMinutes":490,"cookMinutes":5,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Bircher","items":[{"item":"rolled oats","raw":"200g rolled oats","quantity":200,"unit":"g","ingredientId":"rolled-oats"},{"item":"green apples","raw":"2 green apples, coarsely grated","quantity":2,"ingredientId":"apple","prep":"coarsely grated"},{"item":"milk","raw":"250ml milk","quantity":250,"unit":"ml","ingredientId":"milk"},{"item":"apple juice","raw":"125ml apple juice","quantity":125,"unit":"ml","ingredientId":"apple-juice"},{"item":"Greek yoghurt","raw":"200g Greek yoghurt","quantity":200,"unit":"g","ingredientId":"greek-yoghurt"},{"item":"honey","raw":"1 tbsp honey","quantity":1,"unit":"tbsp","ingredientId":"honey"},{"item":"ground cinnamon","raw":"1/2 tsp ground cinnamon","quantity":0.5,"unit":"tsp","ingredientId":"ground-cinnamon"}]},{"title":"To top","items":[{"item":"flaked almonds","raw":"40g flaked almonds","quantity":40,"unit":"g","ingredientId":"almonds"},{"item":"pepitas","raw":"2 tbsp pepitas","quantity":2,"unit":"tbsp","ingredientId":"pumpkin-seeds"},{"item":"frozen mixed berries","raw":"150g frozen mixed berries, thawed (or fresh berries)","quantity":150,"unit":"g","ingredientId":"frozen-berries","prep":"thawed","note":"or fresh berries"},{"item":"Extra honey","raw":"Extra honey, to serve","ingredientId":"honey","prep":"to serve"}]}],"steps":[{"text":"The night before, stir the oats, grated apple (skin and all), milk, apple juice, yoghurt, honey and cinnamon together in a bowl or container. Cover and refrigerate overnight, or for at least 8 hours."},{"text":"In the morning, toast the almonds and pepitas in a dry frying pan over medium heat for 4 to 5 minutes, shaking the pan, until golden. Tip onto a plate to cool."},{"text":"Stir the bircher. If it's too thick, loosen with a splash of milk. Spoon into bowls and top with berries, the toasted nuts and seeds, and a drizzle of honey."}],"notes":["Start the night before: the oats soak overnight.","It keeps for 3 days in the fridge, so a double batch on Sunday covers most of the week."],"source":"user","provenance":"ai-draft"}},{"slug":"corn-fritters","title":"Corn Fritters with Avocado Salsa","cuisine":"modern-australian","meal_types":["breakfast","lunch"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":35,"recipe":{"id":"corn-fritters","title":"Corn Fritters with Avocado Salsa","summary":"Crisp, golden corn and feta fritters with a sharp, chunky avocado and tomato salsa.","cuisine":"modern-australian","diets":["vegetarian"],"mealTypes":["breakfast","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":20,"servings":4,"onePot":false,"seasons":["summer","autumn"],"ingredientGroups":[{"title":"Fritters","items":[{"item":"corn kernels","raw":"400g corn kernels (frozen and thawed, or cut from 3 cobs)","quantity":400,"unit":"g","ingredientId":"corn-kernels","note":"frozen and thawed, or cut from 3 cobs"},{"item":"self-raising flour","raw":"150g self-raising flour","quantity":150,"unit":"g","ingredientId":"self-raising-flour"},{"item":"eggs","raw":"2 eggs","quantity":2,"ingredientId":"egg"},{"item":"milk","raw":"125ml milk","quantity":125,"unit":"ml","ingredientId":"milk"},{"item":"spring onions","raw":"3 spring onions, finely sliced","quantity":3,"ingredientId":"spring-onion","prep":"finely sliced"},{"item":"feta","raw":"100g feta, crumbled","quantity":100,"unit":"g","ingredientId":"feta","prep":"crumbled"},{"item":"smoked paprika","raw":"1/2 tsp smoked paprika","quantity":0.5,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"neutral oil","raw":"60ml neutral oil, for frying","quantity":60,"unit":"ml","ingredientId":"neutral-oil","prep":"for frying"}]},{"title":"Avocado salsa","items":[{"item":"avocados","raw":"2 avocados, diced","quantity":2,"ingredientId":"avocado","prep":"diced"},{"item":"cherry tomatoes","raw":"250g cherry tomatoes, quartered","quantity":250,"unit":"g","ingredientId":"cherry-tomato","prep":"quartered"},{"item":"small red onion","raw":"1/2 small red onion, finely diced","quantity":0.5,"ingredientId":"red-onion","prep":"finely diced"},{"item":"long red chilli","raw":"1 long red chilli, seeded and finely chopped","quantity":1,"ingredientId":"red-chilli","prep":"seeded and finely chopped"},{"item":"coriander leaves","raw":"Handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"},{"item":"lime","raw":"Juice of 1 lime","quantity":1,"ingredientId":"lime","prep":"juiced"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"}]}],"steps":[{"text":"Make the salsa first so the onion mellows: gently mix everything in a bowl and set aside."},{"text":"Whisk the flour, eggs and milk in a large bowl to a thick, smooth batter. Fold in the corn, spring onion, feta, paprika and salt."},{"text":"Heat half the oil in a large frying pan over medium heat. Drop in 1/4 cup of batter per fritter, flatten slightly, and cook for 3 minutes each side until deep golden and cooked through. Drain on paper towel."},{"text":"Repeat with the remaining batter, adding more oil as needed. Keep the cooked fritters warm in a low oven."},{"text":"Serve the fritters stacked, with the salsa spooned over."}],"notes":["Pat thawed corn dry on paper towel. Wet corn makes the batter thin and the fritters soggy.","Add a few rashers of crisp bacon on the side if you're not cooking for vegetarians."],"source":"user","provenance":"ai-draft"}},{"slug":"chicken-ginger-congee","title":"Chicken and Ginger Congee","cuisine":"chinese","meal_types":["breakfast","lunch"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":85,"recipe":{"id":"chicken-ginger-congee","title":"Chicken and Ginger Congee","summary":"Silky rice porridge with poached chicken and ginger, finished with soy, sesame and spring onion.","cuisine":"chinese","diets":["no-dairy"],"mealTypes":["breakfast","lunch"],"difficulty":"easy","prepMinutes":10,"cookMinutes":75,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Congee","items":[{"item":"jasmine rice","raw":"200g jasmine rice, rinsed","quantity":200,"unit":"g","ingredientId":"jasmine-rice","prep":"rinsed"},{"item":"chicken stock","raw":"1L chicken stock","quantity":1,"unit":"l","ingredientId":"chicken-stock"},{"item":"water","raw":"1L water","quantity":1,"unit":"l","ingredientId":"water"},{"item":"piece ginger","raw":"5cm piece ginger, peeled and cut into thin matchsticks","quantity":5,"unit":"cm","ingredientId":"ginger","prep":"peeled and cut into thin matchsticks"},{"item":"chicken thigh fillets","raw":"500g chicken thigh fillets","quantity":500,"unit":"g","ingredientId":"chicken-thigh"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"ground white pepper","raw":"1/4 tsp ground white pepper","quantity":0.25,"unit":"tsp","ingredientId":"white-pepper"}]},{"title":"To top","items":[{"item":"spring onions","raw":"3 spring onions, finely sliced","quantity":3,"ingredientId":"spring-onion","prep":"finely sliced"},{"item":"soy sauce","raw":"2 tbsp soy sauce","quantity":2,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"sesame oil","raw":"2 tsp sesame oil","quantity":2,"unit":"tsp","ingredientId":"sesame-oil"},{"item":"fried shallots","raw":"2 tbsp fried shallots","quantity":2,"unit":"tbsp","ingredientId":"fried-shallots"},{"item":"coriander leaves","raw":"Handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander"}]}],"steps":[{"text":"Put the rice, stock, water and half the ginger in a large heavy pot. Bring to the boil, stirring so the rice doesn't catch, until the liquid is bubbling steadily."},{"text":"Add the chicken whole. Turn the heat to low, partly cover and simmer for 20 minutes, until the chicken is cooked through (75°C in the thickest part). Lift it out onto a board."},{"text":"Keep the congee at a gentle simmer, partly covered, for another 45 to 50 minutes, stirring every 10 minutes and scraping the bottom, until the rice has broken down into a thick, silky porridge. Add a splash of water if it gets too thick."},{"text":"Shred the chicken with two forks. Stir it back in with the salt and white pepper and warm through."},{"text":"Ladle into bowls. Top with the remaining ginger, spring onion, a drizzle of soy and sesame oil, fried shallots and coriander."}],"notes":["Congee thickens as it sits. Loosen leftovers with hot water or stock, and keep them in the fridge for up to 2 days.","Use tamari instead of soy sauce for a gluten-free bowl (check the stock label too).","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"fattoush","title":"Fattoush","cuisine":"middle-eastern","meal_types":["lunch","dinner"],"diets":["vegetarian","vegan","no-dairy"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"fattoush","title":"Fattoush","summary":"A crunchy Lebanese salad of crisp pita, cucumber, tomato and herbs in a sumac dressing.","cuisine":"middle-eastern","diets":["vegetarian","vegan","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":10,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Salad","items":[{"item":"large pita breads","raw":"2 large pita breads","quantity":2,"ingredientId":"pita"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"baby cos lettuce","raw":"1 baby cos lettuce, roughly chopped","quantity":1,"ingredientId":"cos-lettuce","prep":"roughly chopped"},{"item":"tomatoes","raw":"3 tomatoes, cut into chunks","quantity":3,"ingredientId":"tomato","prep":"cut into chunks"},{"item":"Lebanese cucumbers","raw":"2 Lebanese cucumbers, halved and sliced","quantity":2,"ingredientId":"cucumber","prep":"halved and sliced"},{"item":"radishes","raw":"6 radishes, thinly sliced","quantity":6,"ingredientId":"radish","prep":"thinly sliced"},{"item":"spring onions","raw":"4 spring onions, sliced","quantity":4,"ingredientId":"spring-onion","prep":"sliced"},{"item":"flat-leaf parsley leaves","raw":"1 cup flat-leaf parsley leaves","quantity":1,"unit":"cup","ingredientId":"parsley"},{"item":"mint leaves","raw":"1/2 cup mint leaves","quantity":0.5,"unit":"cup","ingredientId":"mint"}]},{"title":"Dressing","items":[{"item":"extra virgin olive oil","raw":"80ml extra virgin olive oil","quantity":80,"unit":"ml","ingredientId":"olive-oil"},{"item":"lemon","raw":"Juice of 1 lemon","quantity":1,"ingredientId":"lemon","prep":"juiced"},{"item":"pomegranate molasses","raw":"1 tbsp pomegranate molasses","quantity":1,"unit":"tbsp","ingredientId":"pomegranate-molasses"},{"item":"garlic","raw":"1 garlic clove, crushed","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"sumac","raw":"2 tsp sumac, plus extra to finish","quantity":2,"unit":"tsp","ingredientId":"sumac","prep":"plus extra to finish"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]}],"steps":[{"text":"Heat the oven to 200°C (180°C fan-forced). Split the pita breads open, tear into bite-sized pieces, toss with the olive oil and spread on a tray. Bake for 8 to 10 minutes, until golden and crisp. Cool."},{"text":"Whisk the dressing ingredients together in a large salad bowl."},{"text":"Add the lettuce, tomato, cucumber, radish, spring onion, parsley and mint and toss well."},{"text":"Add the pita just before serving and toss again, so some pieces soak up the dressing and others stay crunchy. Finish with a pinch of sumac."}],"notes":["Pomegranate molasses gives the dressing its sweet-sour depth. If you don't have it, use 1 tsp honey and an extra squeeze of lemon (it won't be vegan with honey).","Serve with grilled chicken or lamb to make it dinner."],"source":"user","provenance":"ai-draft"}},{"slug":"lemongrass-pork-noodle-salad","title":"Lemongrass Pork Noodle Salad","cuisine":"vietnamese","meal_types":["lunch","dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"medium","total_minutes":55,"recipe":{"id":"lemongrass-pork-noodle-salad","title":"Lemongrass Pork Noodle Salad","summary":"Charred lemongrass pork over cool rice noodles and herbs, with a sweet-sour nuoc cham.","cuisine":"vietnamese","diets":["no-gluten","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"medium","prepMinutes":40,"cookMinutes":15,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Pork","items":[{"item":"pork neck","raw":"600g pork neck (pork scotch), thinly sliced","quantity":600,"unit":"g","ingredientId":"pork-shoulder","prep":"thinly sliced","note":"pork scotch"},{"item":"lemongrass","raw":"2 lemongrass stalks, white part only, finely chopped","quantity":2,"unit":"stalk","ingredientId":"lemongrass","prep":"white part only, finely chopped"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"shallots","raw":"2 shallots, finely chopped","quantity":2,"ingredientId":"shallot","prep":"finely chopped"},{"item":"fish sauce","raw":"2 tbsp fish sauce","quantity":2,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"brown sugar","raw":"2 tbsp brown sugar","quantity":2,"unit":"tbsp","ingredientId":"brown-sugar"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"Nuoc cham","items":[{"item":"fish sauce","raw":"60ml fish sauce","quantity":60,"unit":"ml","ingredientId":"fish-sauce"},{"item":"lime juice","raw":"60ml lime juice","quantity":60,"unit":"ml","ingredientId":"lime"},{"item":"caster sugar","raw":"2 tbsp caster sugar","quantity":2,"unit":"tbsp","ingredientId":"caster-sugar"},{"item":"warm water","raw":"125ml warm water","quantity":125,"unit":"ml","ingredientId":"water"},{"item":"garlic","raw":"1 garlic clove, finely chopped","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"bird's eye chilli","raw":"1 bird's eye chilli, finely chopped","quantity":1,"ingredientId":"birds-eye-chilli","prep":"finely chopped"}]},{"title":"Salad","items":[{"item":"rice vermicelli","raw":"250g rice vermicelli","quantity":250,"unit":"g","ingredientId":"rice-vermicelli"},{"item":"iceberg lettuce","raw":"1/2 iceberg lettuce, shredded","quantity":0.5,"ingredientId":"iceberg-lettuce","prep":"shredded"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, cut into matchsticks","quantity":1,"ingredientId":"cucumber","prep":"cut into matchsticks"},{"item":"carrot","raw":"1 carrot, cut into matchsticks","quantity":1,"ingredientId":"carrot","prep":"cut into matchsticks"},{"item":"bean sprouts","raw":"100g bean sprouts","quantity":100,"unit":"g","ingredientId":"bean-sprouts"},{"item":"mint leaves","raw":"1 cup mint leaves","quantity":1,"unit":"cup","ingredientId":"mint"},{"item":"coriander leaves","raw":"1 cup coriander leaves","quantity":1,"unit":"cup","ingredientId":"coriander"},{"item":"roasted peanuts","raw":"50g roasted peanuts, chopped","quantity":50,"unit":"g","ingredientId":"peanuts","prep":"chopped"}]}],"steps":[{"text":"Mix the pork with the lemongrass, garlic, shallot, fish sauce, sugar, oil and pepper. Cover and marinate in the fridge for 20 minutes (or up to a day)."},{"text":"Make the nuoc cham: stir the fish sauce, lime juice, sugar and warm water until the sugar dissolves, then add the garlic and chilli."},{"text":"Cook the noodles following the packet instructions, rinse under cold water until cool, and drain well."},{"text":"Heat a large frying pan or barbecue grill plate over high heat. Cook the pork in batches in a single layer, 2 to 3 minutes each side, until caramelised at the edges and cooked through."},{"text":"Divide the lettuce, noodles, cucumber, carrot, sprouts and herbs between bowls. Top with the pork and peanuts and pour over a few spoonfuls of nuoc cham. Serve the rest on the side."}],"notes":["Ask the butcher to slice the pork thinly, or freeze it for 30 minutes so it's easy to slice yourself.","Pork mince works too: shape the marinated mince into small flat patties and cook them through.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"gado-gado","title":"Gado-Gado","cuisine":"indonesian","meal_types":["lunch","dinner"],"diets":["vegetarian","no-dairy"],"difficulty":"easy","total_minutes":45,"recipe":{"id":"gado-gado","title":"Gado-Gado","summary":"Warm potatoes, eggs, tofu and crunchy vegetables under a rich, spicy peanut sauce.","cuisine":"indonesian","diets":["vegetarian","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":25,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Peanut sauce","items":[{"item":"crunchy peanut butter","raw":"160g crunchy peanut butter","quantity":160,"unit":"g","ingredientId":"peanut-butter"},{"item":"coconut milk","raw":"200ml coconut milk","quantity":200,"unit":"ml","ingredientId":"coconut-milk"},{"item":"garlic","raw":"1 garlic clove, crushed","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"kecap manis","raw":"2 tbsp kecap manis","quantity":2,"unit":"tbsp","ingredientId":"kecap-manis"},{"item":"sambal oelek","raw":"1-2 tsp sambal oelek","quantity":{"min":1,"max":2},"unit":"tsp","ingredientId":"sambal-oelek"},{"item":"brown sugar","raw":"1 tbsp brown sugar","quantity":1,"unit":"tbsp","ingredientId":"brown-sugar"},{"item":"lime","raw":"Juice of 1 lime","quantity":1,"ingredientId":"lime","prep":"juiced"},{"item":"water","raw":"60ml water","quantity":60,"unit":"ml","ingredientId":"water"}]},{"title":"Salad","items":[{"item":"baby potatoes","raw":"500g baby potatoes, halved","quantity":500,"unit":"g","ingredientId":"waxy-potato","prep":"halved"},{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"green beans","raw":"200g green beans, trimmed","quantity":200,"unit":"g","ingredientId":"green-beans","prep":"trimmed"},{"item":"firm tofu","raw":"300g firm tofu, cut into 2cm cubes","quantity":300,"unit":"g","ingredientId":"tofu","prep":"cut into 2cm cubes"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"cabbage","raw":"1/4 cabbage, shredded","quantity":0.25,"ingredientId":"cabbage","prep":"shredded"},{"item":"bean sprouts","raw":"150g bean sprouts","quantity":150,"unit":"g","ingredientId":"bean-sprouts"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, sliced","quantity":1,"ingredientId":"cucumber","prep":"sliced"},{"item":"tomatoes","raw":"2 tomatoes, cut into wedges","quantity":2,"ingredientId":"tomato","prep":"cut into wedges"},{"item":"fried shallots","raw":"2 tbsp fried shallots","quantity":2,"unit":"tbsp","ingredientId":"fried-shallots"},{"item":"Prawn crackers","raw":"Prawn crackers, to serve (optional)","ingredientId":"prawn-crackers","prep":"to serve","optional":true}]}],"steps":[{"text":"Put all the peanut sauce ingredients in a small saucepan and warm over low heat, stirring, for 5 minutes until smooth and thick enough to coat a spoon. Add a splash of water if it's too thick."},{"text":"Boil the potatoes in salted water for 12 to 15 minutes until tender. Lower the eggs into the same pot for the last 8 minutes, and add the beans for the last 2. Drain, cool the eggs in cold water, then peel and halve."},{"text":"Pat the tofu dry. Fry it in the oil in a non-stick pan over medium-high heat for 8 minutes, turning, until golden on all sides."},{"text":"Arrange the potatoes, beans, eggs, tofu, cabbage, bean sprouts, cucumber and tomato on a platter."},{"text":"Spoon over the warm peanut sauce, scatter with fried shallots and serve with prawn crackers if you like."}],"notes":["Prawn crackers are optional because they contain prawn. Leave them out for a vegetarian table.","The sauce keeps for 5 days in the fridge and is excellent on grilled chicken."],"source":"user","provenance":"ai-draft"}},{"slug":"danish-open-sandwiches","title":"Danish Open Sandwiches","cuisine":"scandinavian","meal_types":["lunch"],"diets":["pescatarian"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"danish-open-sandwiches","title":"Danish Open Sandwiches","summary":"Buttered rye topped two ways: smoked salmon with dill, and egg with capers and radish.","cuisine":"scandinavian","diets":["pescatarian"],"mealTypes":["lunch"],"difficulty":"easy","prepMinutes":20,"cookMinutes":10,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Base","items":[{"item":"dark rye bread","raw":"8 slices dark rye bread","quantity":8,"unit":"slice","ingredientId":"rye-bread"},{"item":"butter","raw":"40g butter, softened","quantity":40,"unit":"g","ingredientId":"butter","prep":"softened"}]},{"title":"Smoked salmon","items":[{"item":"creme fraiche","raw":"100g creme fraiche","quantity":100,"unit":"g","ingredientId":"creme-fraiche"},{"item":"lemon zest","raw":"1 tsp lemon zest","quantity":1,"unit":"tsp","ingredientId":"lemon"},{"item":"smoked salmon","raw":"200g smoked salmon","quantity":200,"unit":"g","ingredientId":"smoked-salmon"},{"item":"Lebanese cucumber","raw":"1/2 Lebanese cucumber, very thinly sliced","quantity":0.5,"ingredientId":"cucumber","prep":"very thinly sliced"},{"item":"red onion","raw":"1/4 red onion, very thinly sliced","quantity":0.25,"ingredientId":"red-onion","prep":"very thinly sliced"},{"item":"dill sprigs","raw":"2 tbsp dill sprigs","quantity":2,"unit":"tbsp","ingredientId":"dill"}]},{"title":"Egg","items":[{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"whole-egg mayonnaise","raw":"60g whole-egg mayonnaise","quantity":60,"unit":"g","ingredientId":"mayonnaise"},{"item":"Dijon mustard","raw":"1 tsp Dijon mustard","quantity":1,"unit":"tsp","ingredientId":"dijon-mustard"},{"item":"capers","raw":"1 tbsp capers, rinsed","quantity":1,"unit":"tbsp","ingredientId":"capers","prep":"rinsed"},{"item":"radishes","raw":"4 radishes, thinly sliced","quantity":4,"ingredientId":"radish","prep":"thinly sliced"},{"item":"chives","raw":"1 tbsp chives, finely chopped","quantity":1,"unit":"tbsp","ingredientId":"chives","prep":"finely chopped"},{"item":"Black pepper","raw":"Black pepper","ingredientId":"black-pepper"}]}],"steps":[{"text":"Lower the eggs into boiling water and cook for 10 minutes, until the yolks are firm and set. Cool in cold water, peel and slice."},{"text":"Mix the creme fraiche with the lemon zest. Stir the mayonnaise and mustard together in a separate bowl."},{"text":"Butter every slice of rye right to the edges."},{"text":"For the salmon sandwiches, spread four slices with the creme fraiche, drape over the salmon and top with cucumber, red onion and dill."},{"text":"For the egg sandwiches, spread the other four slices with the mustard mayonnaise, cover with sliced egg and finish with radish, capers, chives and black pepper. Eat with a knife and fork."}],"notes":["Cold-smoked salmon isn't recommended for pregnant people, young children, older people or anyone with a weakened immune system. Use hot-smoked salmon instead.","Dense, dark rye is the traditional base. Light rye works but tears more easily under the toppings."],"source":"user","provenance":"ai-draft"}},{"slug":"spanish-tortilla","title":"Spanish Tortilla","cuisine":"spanish","meal_types":["lunch","dinner","snack"],"diets":["vegetarian","no-gluten","no-dairy"],"difficulty":"medium","total_minutes":65,"recipe":{"id":"spanish-tortilla","title":"Spanish Tortilla","summary":"A thick, golden potato and onion omelette, soft in the middle, good warm or cold.","cuisine":"spanish","diets":["vegetarian","no-gluten","no-dairy"],"mealTypes":["lunch","dinner","snack"],"difficulty":"medium","prepMinutes":20,"cookMinutes":45,"servings":6,"onePot":false,"ingredientGroups":[{"items":[{"item":"waxy potatoes","raw":"700g waxy potatoes, peeled and thinly sliced","quantity":700,"unit":"g","ingredientId":"waxy-potato","prep":"peeled and thinly sliced"},{"item":"brown onion","raw":"1 brown onion, thinly sliced","quantity":1,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"olive oil","raw":"250ml olive oil","quantity":250,"unit":"ml","ingredientId":"olive-oil"},{"item":"eggs","raw":"6 eggs","quantity":6,"ingredientId":"egg"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"Green salad","raw":"Green salad","ingredientId":"salad-leaves"},{"item":"Aioli","raw":"Aioli (optional)","ingredientId":"aioli","optional":true}]}],"steps":[{"text":"Heat the oil in a 24cm non-stick frying pan over medium-low heat. Add the potato and onion with half the salt and cook gently for 20 to 25 minutes, turning now and then, until the potato is completely tender but barely coloured."},{"text":"Set a sieve over a heatproof bowl and drain the potato and onion, keeping the oil. Cool for 5 minutes."},{"text":"Beat the eggs with the remaining salt in a large bowl. Fold in the potato and onion and leave for 5 minutes so the potato soaks up some egg."},{"text":"Wipe the pan, add 2 tbsp of the saved oil and heat over medium heat. Pour in the mixture, flatten it, and cook for 6 to 8 minutes, running a spatula round the edge, until the base is golden and the sides are set."},{"text":"Put a flat plate bigger than the pan on top. Holding both firmly, flip the tortilla onto the plate, then slide it back into the pan cooked side up. Cook for another 4 to 5 minutes, until a skewer in the centre comes out with no liquid egg."},{"text":"Slide onto a board and rest for 10 minutes before cutting into wedges. Serve warm or at room temperature with a green salad and aioli."}],"notes":["Keep the leftover potato oil in a jar in the fridge. It's full of flavour for frying.","The flip is the only tricky part: do it in one confident move over the sink."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;